# Early startup safety: keep double-click launches from silently closing.
def _early_crash_handler(exc_type, exc_value, exc_tb):
  text = "".join(traceback.format_exception(exc_type, exc_value, exc_tb)) if "traceback" in globals() else f"{exc_type.__name__}: {exc_value}"
  try:
    local = Path(os.getenv("LOCALAPPDATA") or (Path.home() / "AppData" / "Local")) / "NEXUS_OS"
    local.mkdir(parents=True, exist_ok=True)
    (local / "startup_crash.log").write_text(text, encoding="utf-8")
  except Exception:
    pass
  try:
    ctypes.windll.user32.MessageBoxW(0, text, "NEXUS OS – Startfehler", 0x10)
  except Exception:
    pass


