def _load_persistent_audio_devices():
  try:
    if AUDIO_CFG.exists():
      data = json.loads(AUDIO_CFG.read_text(encoding="utf-8"))
      if isinstance(data, dict):
        return data
  except Exception:
    pass
  return {}


def _save_persistent_audio_devices(data):
  try:
    AUDIO_CFG.parent.mkdir(parents=True, exist_ok=True)
    tmp = AUDIO_CFG.with_suffix(".tmp")
    tmp.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    tmp.replace(AUDIO_CFG)
  except Exception:
    pass

