      add_row("Samplerate",self.cap_audio_rate_var,["44100","48000","96000"]); add_row("Audio-Bitrate",self.cap_audio_bitrate_var,["96","128","160","192","256","320"]); add_check("Audio aufnehmen",self.cap_record_audio_var)
