      ctk.CTkButton(body,text="⚡ AUTO-OPTIMIERUNG FÜR DIESES SYSTEM",command=self._nxcap_auto_optimize,fg_color=THEME["accent_green"],text_color="#000",height=38).pack(anchor="w",padx=12,pady=12)
