    # PREVIEW
    preview=ctk.CTkFrame(work,fg_color="#000000",border_color=BORDER,border_width=1); preview.grid(row=0,column=0,sticky="nsew",padx=3,pady=3); preview.grid_rowconfigure(1,weight=1); preview.grid_columnconfigure(0,weight=1)
