  def page_core_engines(self):
    """Build the Core Engines page inside NEXUS' normal navigation view."""
    v=self.views["core_engines"]
    for _w in v.winfo_children():
      try: _w.destroy()
      except Exception: pass
    f=ctk.CTkFrame(v,fg_color="transparent"); f.pack(fill="both",expand=True,padx=14,pady=12)
    f.grid_columnconfigure(0,weight=1); f.grid_rowconfigure(2,weight=1)
    head=ctk.CTkFrame(f,fg_color=THEME["card"],border_color=THEME["accent_cyan"],border_width=1,corner_radius=12); head.grid(row=0,column=0,sticky="ew",pady=(0,8))
    ctk.CTkLabel(head,text="⚡ NEXUS CORE ENGINES",font=("Segoe UI",24,"bold"),text_color=THEME["accent_cyan"]).pack(side="left",padx=14,pady=10)
    ctk.CTkLabel(head,text="VISION • AUDIO • MEDIA • CONTROLLER • IMAGE • DATA",font=("Consolas",10,"bold"),text_color=THEME["muted"]).pack(side="left",padx=4)
    status=tk.StringVar(value="Bereit — lokale Engines werden nur bei Bedarf geladen.")
