# ===================== NEXUS DOMAIN AI 2026 =====================
class NexusDomainAI:
  """Bereichsspezifische KI mit Chat, Sprache und kontrollierten Werkzeugen."""
  DOMAINS={
    "start":("NEXUS Core", "System-/Startassistent"),
    "config":("NEXUS Config AI", "Konfiguration und Speicherung"),
    "game":("NEXUS Gaming AI", "Gaming, FPS, Optimierung und HUD"),
    "benchmark":("NEXUS Benchmark AI", "Benchmarks und Performanceanalyse"),
    "ai":("NEXUS Agent AI", "KI/Agent und Automatisierung"),
    "media":("NEXUS Media AI", "Bild, Video, ComfyUI und Wan2.1"),
    "music":("NEXUS Music AI", "Musikbibliothek, Playlists, Spotify-Metadaten und Video-Schnitt"),
    "main":("NEXUS OS AI", "Hauptoberfläche und Workflows"),
    "voice":("NEXUS Voice AI", "Voice Assistant und Sprache"),
    "capture":("NEXUS Capture AI", "Aufnahme, Quellen, Audio und Replay"),
    "video":("NEXUS Video AI", "Schnitt, Timeline, Export und Medien"),
    "code":("NEXUS Code AI", "Programmierung, Tests und Projektstruktur"),
    "network":("NEXUS Network AI", "Ping, Netzwerkdiagnose und Adapter"),
    "vault":("NEXUS Security AI", "Passwort-Vault und Sicherheit"),
    "school":("NEXUS Learning AI", "Schule, Lernen, Noten und Planung"),
    "office":("NEXUS Office AI", "Word, Excel, Präsentation, PDF, Mail"),
    "settings":("NEXUS Settings AI", "Einstellungen und Personalisierung"),
  }
  RISKY={"game_boost","kill_process","send_mail","overwrite_file","change_setting","start_recording"}

  def __init__(self,app,domain="main"):
    self.app=app; self.domain=domain if domain in self.DOMAINS else "main"; self.win=None
    self.history=[]; self.pending=None

  def open(self,domain=None):
    if domain in self.DOMAINS:self.domain=domain
    if self.win is not None:
      try:
        if self.win.winfo_exists(): self.win.deiconify(); self.win.lift(); self._refresh_header(); return
      except Exception: pass
    self.win=ctk.CTkToplevel(self.app); self.win.title(self.DOMAINS[self.domain][0]+" // Bereichs-KI")
    self.win.geometry("1050x720"); self.win.minsize(820,560); self.win.configure(fg_color=THEME["bg"])
    self.win.grid_columnconfigure(0,weight=1); self.win.grid_rowconfigure(2,weight=1)
    head=ctk.CTkFrame(self.win,fg_color=THEME["card"],border_color=THEME["accent_green"],border_width=1); head.grid(row=0,column=0,sticky="ew",padx=10,pady=10)
    self.head=ctk.CTkLabel(head,text="",font=("Consolas",19,"bold"),text_color=THEME["accent_green"]); self.head.pack(side="left",padx=14,pady=9)
    self.domain_var=ctk.StringVar(value=self.domain)
    ctk.CTkOptionMenu(head,variable=self.domain_var,values=list(self.DOMAINS.keys()),command=self._domain_changed,width=180).pack(side="left",padx=8)
    self.status=ctk.CTkLabel(head,text="Bereit",font=("Consolas",10),text_color=THEME["subtext"]); self.status.pack(side="right",padx=14)
    quick=ctk.CTkFrame(self.win,fg_color=THEME["card"],border_color=THEME["border"],border_width=1); quick.grid(row=1,column=0,sticky="ew",padx=10,pady=(0,8))
    ctk.CTkLabel(quick,text="⚡ SCHNELLSTART",font=("Consolas",10,"bold"),text_color=THEME["accent_cyan"]).pack(side="left",padx=(10,5))
    self.quickbar=ctk.CTkFrame(quick,fg_color="transparent"); self.quickbar.pack(side="left",fill="x",expand=True)
    self._build_quick_actions()
    body=ctk.CTkFrame(self.win,fg_color=THEME["card"]); body.grid(row=2,column=0,sticky="nsew",padx=10,pady=(0,10)); body.grid_rowconfigure(0,weight=1); body.grid_columnconfigure(0,weight=1)
    self.chat=ctk.CTkTextbox(body,font=("Consolas",12),fg_color="#050705",text_color=THEME["text"],wrap="word"); self.chat.grid(row=0,column=0,columnspan=3,sticky="nsew",padx=8,pady=8); self.chat.configure(state="disabled")
    bar=ctk.CTkFrame(body,fg_color="transparent"); bar.grid(row=1,column=0,columnspan=3,sticky="ew",padx=8,pady=(0,8)); bar.grid_columnconfigure(0,weight=1)
    self.input=ctk.CTkEntry(bar,placeholder_text="Schreibe einen Befehl oder eine Frage für diesen Bereich…",font=("Consolas",12)); self.input.grid(row=0,column=0,sticky="ew",padx=(0,6)); self.input.bind("<Return>",lambda e:self.ask())
    self.app.btn(bar,"🎙️ REDEN",self.listen,THEME["accent_purple"],"#fff",100,34,9).grid(row=0,column=1,padx=3)
    self.app.btn(bar,"➤ SENDEN",self.ask,THEME["accent_green"],"#000",100,34,9).grid(row=0,column=2,padx=3)
    self.app.btn(bar,"🧰 WERKZEUGE",self.show_tools,THEME["accent_cyan"],"#000",115,34,9).grid(row=0,column=3,padx=3)
    self._refresh_header(); self._append("NEXUS KI",f"Bereichs-KI bereit: {self.DOMAINS[self.domain][1]}\nIch kann erklären, planen und definierte Aktionen in diesem Bereich ausführen.")

  def _build_quick_actions(self):
    labels={"game":[("🎮 Boost prüfen","Wie kann ich mein Spiel sicher optimieren?"),("📈 FPS","Analysiere meine Gaming-Performance.")],"benchmark":[("🏁 Benchmark","Bereite einen sauberen Benchmark vor."),("📊 Ergebnis","Erkläre meine Benchmark-Werte.")],"office":[("📝 Word","Öffne Word und hilf mir beim Dokument."),("📊 Excel","Öffne Excel und hilf mir bei einer Tabelle."),("🎞️ Präsentation","Erstelle eine Präsentationsstruktur.")],"school":[("📚 Lernen","Erstelle mir einen Lernplan."),("🧠 Quiz","Erstelle ein Quiz zu meinem Thema."),("📝 Noten","Analysiere meine Noten.")],"music":[("🎵 Musik finden","Suche in meiner NEXUS-Musikbibliothek."),("🧠 Musik-Cut","Plane einen Beat-synchronen Schnitt mit einem lokalen Track.")],"video":[("✂️ Schnitt","Erstelle einen Schnittplan für mein Projekt."),("🎬 Timeline","Wie baue ich diese Timeline auf?")],"capture":[("📹 Aufnahme","Hilf mir, die Aufnahme einzurichten."),("🎙️ Audio","Optimiere Mikrofon und Desktop-Audio.")],"code":[("💻 Code prüfen","Analysiere mein Projekt auf Fehler."),("🧪 Testplan","Erstelle einen Testplan für mein Projekt.")],"network":[("🌐 Ping","Führe einen Ping-Test durch."),("📡 Netzwerk","Analysiere mein Netzwerk.")],"media":[("🎬 Workflow","Plane einen Wan2.1-Workflow."),("🖼️ Bild","Plane eine Bildgenerierung.")],"vault":[("🔐 Sicherheit","Prüfe die Vault-Sicherheit."),("🔑 Passwort","Erstelle ein sicheres Passwort-Konzept.")],"settings":[("⚙️ Einstellungen","Welche Einstellungen sollte ich prüfen?"),("🎨 UI","Hilf mir bei der NEXUS-Oberfläche.")] }
    for child in self.quickbar.winfo_children(): child.destroy()
    for label,prompt in labels.get(self.domain,[("💡 Hilfe","Was kannst du in diesem Bereich für mich tun?")]):
      self.app.btn(self.quickbar,label,lambda p=prompt:self._quick_prompt(p),THEME["bg"],THEME["text"],125,30,9).pack(side="left",padx=3,pady=5)
  def _quick_prompt(self,prompt):
    self.input.delete(0,"end"); self.input.insert(0,prompt); self.ask()

  def _domain_changed(self,d):
    if d in self.DOMAINS:self.domain=d
    self._refresh_header(); self._build_quick_actions(); self._append("SYSTEM",f"Bereich gewechselt zu: {self.DOMAINS[self.domain][0]}")

  def _refresh_header(self):
    if getattr(self,"head",None): self.head.configure(text=f"🤖 {self.DOMAINS[self.domain][0]}  •  {self.DOMAINS[self.domain][1]}")
    if getattr(self,"win",None): self.win.title(self.DOMAINS[self.domain][0]+" // Bereichs-KI")

  def _append(self,who,msg):
    if not getattr(self,"chat",None):return
    self.chat.configure(state="normal"); self.chat.insert("end",f"\n[{who}]\n{msg}\n"); self.chat.see("end"); self.chat.configure(state="disabled")

  def _context(self):
    c={"domain":self.domain,"name":self.DOMAINS[self.domain][0],"description":self.DOMAINS[self.domain][1]}
    try:
      if self.domain in ("game","benchmark") and getattr(self.app,"game_opt",None): c["game_optimizer"]="bereit"
      if self.domain=="video" and getattr(self.app,"_video_studio_suite",None): c["video_studio"]="geöffnet"
      if self.domain=="office" and getattr(self.app,"_office_suite",None): c["office_suite"]="geöffnet"
      if self.domain=="network": c["network_targets"]=["192.168.1.1","1.1.1.1","8.8.8.8"]
      if self.domain=="school": c["grades_count"]=len(getattr(self.app,"noten",[]) or [])
    except Exception: pass
    return c

  def ask(self):
    q=self.input.get().strip()
    if not q:return
    self.input.delete(0,"end"); self._append("DU",q)
    threading.Thread(target=self._ask_worker,args=(q,),daemon=True).start()

  def _ask_worker(self,q):
    try:
      result=self._tool_command(q)
      if result is not None: ans=result
      else: ans=self._llm(q)
    except Exception as e: ans=f"❌ KI-Fehler: {e}"
    try:self.win.after(0,lambda:self._append(self.DOMAINS[self.domain][0],ans))
    except Exception:pass

  def _llm(self,q):
    system=(f"Du bist {self.DOMAINS[self.domain][0]}, die spezialisierte KI von NEXUS. "
            f"Bereich: {self.DOMAINS[self.domain][1]}. Erkläre praktisch auf Deutsch. "
            "Du darfst keine Aktionen behaupten, die du nicht über ein NEXUS-Werkzeug ausgeführt hast. "
            "Wenn eine Aktion nötig ist, nenne den passenden Befehl und frage bei riskanten Aktionen nach Bestätigung. "
            f"Aktueller Kontext: {json.dumps(self._context(),ensure_ascii=False)}")
    # Ollama zuerst, da NEXUS offline-first sein soll.
    if ollama:
      model=str(self.app.cfg.get("ai_model","qwen2.5-coder:7b"))
      try:
        r=ollama.chat(model=model,messages=[{"role":"system","content":system},{"role":"user","content":q}],options={"temperature":0.25})
        return str(r.get("message",{}).get("content","")).strip() or "Keine Antwort vom lokalen Modell."
      except Exception: pass
    if getattr(self.app,"gclient",None):
      try:
        r=self.app.gclient.chat.completions.create(model=self.app.cfg.get("ai_model","llama-3.3-70b-versatile"),messages=[{"role":"system","content":system},{"role":"user","content":q}],temperature=0.25)
        return str(r.choices[0].message.content)
      except Exception: pass
    return "Ich bin lokal verfügbar, aber momentan ist kein KI-Modell erreichbar. Nutze z. B. 'Werkzeuge' für direkte NEXUS-Funktionen."

  def _tool_command(self,q):
    x=q.lower().strip()
    if x in ("hilfe","tools","werkzeuge","was kannst du"):
      return self._tool_help()
    if x.startswith("bestätige ") and self.pending:
      action,args=self.pending; self.pending=None
      return self._execute(action,args,confirmed=True)
    if self.domain=="game" and any(k in x for k in ("boost","optimier")):
      self.pending=("game_boost",{}); return "⚠️ Gaming-Optimierung kann System-/Spielprozesse verändern. Schreibe **bestätige** zum Ausführen."
    if self.domain=="game" and "restore" in x:
      return self._execute("game_restore",{})
    if self.domain=="benchmark" and ("start" in x or "benchmark" in x):
      return self._execute("benchmark_start",{})
    if self.domain=="network" and "ping" in x:
      host="1.1.1.1"
      m=re.search(r"ping\s+([\w.:-]+)",x)
      if m:host=m.group(1)
      return self._execute("ping",{"host":host})
    if self.domain=="video" and "ki plan" in x:
      try:return "🎬 " + str(self.app._video_studio_suite.ai_edit())
      except Exception:return "Öffne zuerst das NEXUS Video Studio."
    if self.domain=="office" and ("word" in x or "dokument" in x) and ("öff" in x or "star" in x):
      try:self.app._nexus_open_office(); self.app._office_suite.word(); return "📝 NEXUS Word wurde geöffnet."
      except Exception as e:return f"❌ Word: {e}"
    if self.domain=="office" and ("excel" in x or "tabelle" in x) and ("öff" in x or "star" in x):
      try:self.app._nexus_open_office(); self.app._office_suite.excel(); return "📊 NEXUS Excel wurde geöffnet."
      except Exception as e:return f"❌ Excel: {e}"
    if self.domain=="office" and "präsent" in x and ("öff" in x or "star" in x):
      try:self.app._nexus_open_office(); self.app._office_suite.presentation(); return "🎞️ NEXUS Präsentation wurde geöffnet."
      except Exception as e:return f"❌ Präsentation: {e}"
    if self.domain=="office" and ("studio" in x or "office" in x):
      try:self.app._nexus_open_office(); return "🚀 NEXUS Studio wurde geöffnet."
      except Exception as e:return f"❌ Studio: {e}"
    if self.domain=="settings" and "hacker" in x:
      self.pending=("change_setting",{"key":"color_theme","value":"Hacker Green"}); return "⚠️ Ich kann das Theme ändern. Schreibe **bestätige** zum Anwenden."
    return None

  def _tool_help(self):
    tools={
      "game":"Boost/Optimierung (Bestätigung), Restore",
      "benchmark":"Benchmark starten",
      "network":"Ping <host>",
      "video":"KI-Plan erstellen",
      "office":"NEXUS Studio, Word, Excel, Präsentation, PDF, Notes und Mail öffnen",
      "settings":"Theme ändern (Bestätigung)",
      "school":"Lernplan, Noten und Aufgaben erklären/planen",
      "code":"Projektanalyse und Code-Planung",
      "capture":"Aufnahme-Workflows erklären und steuern, wenn verfügbar",
      "media":"ComfyUI/Wan2.1-Workflows planen",
      "vault":"Sicherheits- und Vault-Hilfe",
    }
    return "Verfügbare Bereichs-Werkzeuge:\n• " + tools.get(self.domain,"Chat, Analyse, Planung und Bereichs-Hilfe.")

  def _execute(self,action,args,confirmed=False):
    if action in self.RISKY and not confirmed:
      self.pending=(action,args); return "⚠️ Diese Aktion benötigt deine Bestätigung. Schreibe **bestätige** zum Ausführen."
    if action=="game_boost":
      try:return "🎮 "+str(self.app.game_opt.apply(self.app.cfg.get("game_profile","Balanced")))
      except Exception as e:return f"❌ Gaming: {e}"
    if action=="game_restore":
      try:return "🔄 "+str(self.app.game_opt.restore())
      except Exception as e:return f"❌ Restore: {e}"
    if action=="benchmark_start":
      try:
        self.app._activate_view("benchmark"); return "📊 Benchmark-Bereich geöffnet. Starte den Benchmark dort mit den gewählten Einstellungen."
      except Exception as e:return f"❌ Benchmark: {e}"
    if action=="ping":
      try:
        r=subprocess.run(["ping","-n","4",str(args["host"])],capture_output=True,text=True,timeout=12,creationflags=getattr(subprocess,"CREATE_NO_WINDOW",0)); return r.stdout[-1800:] or "Keine Ping-Antwort."
      except Exception as e:return f"❌ Ping: {e}"
    if action=="change_setting":
      try:self.app.cfg[args["key"]]=args["value"]; save_config(self.app.cfg); return "⚙️ Einstellung gespeichert."
      except Exception as e:return f"❌ Einstellung: {e}"
    return "Werkzeug nicht verfügbar."

  def listen(self):
    if not speech_recognition:
      self._append("VOICE","SpeechRecognition ist nicht installiert."); return
    def worker():
      try:
        r=speech_recognition.Recognizer()
        with speech_recognition.Microphone() as source:
          self._append("VOICE","🎙️ Ich höre…")
          audio=r.listen(source,timeout=5,phrase_time_limit=15)
        text=r.recognize_google(audio,language="de-DE")
        self.win.after(0,lambda:(self.input.delete(0,"end"),self.input.insert(0,text),self.ask()))
      except Exception as e:
        try:self.win.after(0,lambda:self._append("VOICE",f"Spracherkennung: {e}"))
        except Exception:pass
    threading.Thread(target=worker,daemon=True).start()

  def show_tools(self):
    self._append("TOOLS",self._tool_help())


def _nexus_open_domain_ai(self,domain="main"):
  try:
    ai=getattr(self,"_domain_ai",None)
    if ai is None: ai=self._domain_ai=NexusDomainAI(self,domain)
    ai.open(domain)
  except Exception as e:
    try:self._game_log(f"Bereichs-KI: {e}")
    except Exception:pass



class NEXUSOfficeSuite:
  def __init__(self, app):
    self.app=app
    self.win=None
    self.current_page=None
    self.recent=[]
    self._open_window()

  def _open_window(self):
    import tkinter as tk
    if self.win is not None:
      try:
        if self.win.winfo_exists():
          self.win.deiconify(); self.win.lift(); return
      except Exception: pass
    self.win=ctk.CTkToplevel(self.app)
    self.win.title("NEXUS OFFICE SUITE // Word • Excel • Präsentation • PDF • Notes • Tasks • Mail")
    self.win.geometry("1500x920"); self.win.minsize(1150,720)
    self.win.configure(fg_color=THEME["bg"])
    self.win.protocol("WM_DELETE_WINDOW", self.win.withdraw)
    self.win.grid_columnconfigure(1,weight=1); self.win.grid_rowconfigure(1,weight=1)

    head=ctk.CTkFrame(self.win,fg_color=THEME["card"],border_color=THEME["accent_cyan"],border_width=1)
    head.grid(row=0,column=0,columnspan=2,sticky="ew",padx=10,pady=10)
    ctk.CTkLabel(head,text="📚 NEXUS OFFICE SUITE",font=("Consolas",22,"bold"),
                 text_color=THEME["accent_cyan"]).pack(side="left",padx=16,pady=10)
    ctk.CTkLabel(head,text="Offline-first • lokale Dateien • NEXUS KI",font=("Consolas",11),
                 text_color=THEME["subtext"]).pack(side="left",padx=10)
    self.status=ctk.CTkLabel(head,text="Bereit",font=("Consolas",11),text_color=THEME["subtext"])
    self.status.pack(side="right",padx=16)

    nav=ctk.CTkFrame(self.win,fg_color=THEME["card"],border_color=THEME["border"],border_width=1)
    nav.grid(row=1,column=0,sticky="ns",padx=(10,6),pady=(0,10))
    self.body=ctk.CTkFrame(self.win,fg_color=THEME["card"],border_color=THEME["border"],border_width=1)
    self.body.grid(row=1,column=1,sticky="nsew",padx=(0,10),pady=(0,10))
    self.body.grid_rowconfigure(0,weight=1); self.body.grid_columnconfigure(0,weight=1)
    for label,fn in [
      ("📝 WORD",self.word),("📊 EXCEL",self.excel),("🎞️ PRÄSENTATION",self.presentation),
      ("📄 PDF",self.pdf_tools),("📒 NOTES",self.notes),("✅ TASKS",self.tasks),
      ("📅 KALENDER",self.calendar),("✉️ MAIL",self.mail),("⬡ WHITEBOARD",self.whiteboard),
      ("🎬 VIDEO STUDIO",self.video_studio),("🤖 BEREICHS-KI",lambda:self.app._nexus_open_domain_ai("office")),("🏠 WORKSPACE",self.workspace)
    ]:
      self.app.btn(nav,label,fn,THEME["card"],THEME["text"],245,40,10).pack(fill="x",padx=8,pady=3)
    self.workspace()

  def clear(self,title):
    for w in self.body.winfo_children(): w.destroy()
    self.status.configure(text=title)
    return ctk.CTkFrame(self.body,fg_color="transparent")

  def _file(self,types,initial=None):
    from tkinter import filedialog
    return filedialog.askopenfilename(parent=self.win,initialdir=initial or self.app.nexus_paths.get("documents",str(Path.home())),
                                      filetypes=types)

  def _save(self,types,initial=None):
    from tkinter import filedialog
    return filedialog.asksaveasfilename(parent=self.win,initialdir=initial or self.app.nexus_paths.get("documents",str(Path.home())),
                                        filetypes=types)

  def _text_area(self,parent):
    import tkinter as tk
    wrap=ctk.CTkFrame(parent,fg_color="#010302")
    wrap.pack(fill="both",expand=True,padx=8,pady=8)
    txt=tk.Text(wrap,bg="#010302",fg=THEME["text"],insertbackground=THEME["accent_green"],
                selectbackground=THEME["accent_cyan"],font=("Segoe UI",12),undo=True,wrap="word")
    sy=ctk.CTkScrollbar(wrap,command=txt.yview); txt.configure(yscrollcommand=sy.set)
    sy.pack(side="right",fill="y"); txt.pack(side="left",fill="both",expand=True)
    return txt

  # ------------------------------ WORD ------------------------------
  def word(self):
    import tkinter as tk
    from tkinter import font, messagebox
    f=self.clear("📝 NEXUS WORD")
    f.pack(fill="both",expand=True)
    f.grid_rowconfigure(1,weight=1); f.grid_columnconfigure(0,weight=1)
    toolbar=ctk.CTkFrame(f,fg_color=THEME["card"],border_color=THEME["border"],border_width=1)
    toolbar.grid(row=0,column=0,sticky="ew",padx=8,pady=8)
    area=ctk.CTkFrame(f,fg_color="#101010"); area.grid(row=1,column=0,sticky="nsew",padx=8,pady=(0,8))
    area.grid_rowconfigure(0,weight=1); area.grid_columnconfigure(0,weight=1)
    text=tk.Text(area,bg="#f5f5f5",fg="#111111",insertbackground="#111111",font=("Arial",12),
                 undo=True,wrap="word",padx=70,pady=50)
    sy=ctk.CTkScrollbar(area,command=text.yview); text.configure(yscrollcommand=sy.set)
    sy.grid(row=0,column=1,sticky="ns"); text.grid(row=0,column=0,sticky="nsew")
    self.word_text=text; self.word_path=None
    for tag,opts in [
      ("title",{"font":("Arial",24,"bold")}),("h1",{"font":("Arial",18,"bold")}),
      ("h2",{"font":("Arial",15,"bold")}),("bold",{"font":("Arial",12,"bold")}),
      ("italic",{"font":("Arial",12,"italic")}),("underline",{"underline":True})
    ]: text.tag_configure(tag,**opts)

    def apply(tag):
      try: text.tag_add(tag,"sel.first","sel.last")
      except Exception: pass
    def set_align(a):
      tag="align_"+a
      if not text.tag_cget(tag,"justify"): text.tag_configure(tag,justify=a)
      try: text.tag_add(tag,"sel.first","sel.last")
      except Exception: pass
    def bullet():
      try:
        line=text.index("insert linestart")
        text.insert(line,"• ")
      except Exception: pass
    def find():
      q=findvar.get()
      if not q:return
      text.tag_remove("find","1.0","end"); text.tag_configure("find",background="#ffe66d",foreground="#000")
      pos="1.0"
      while True:
        pos=text.search(q,pos,stopindex="end",nocase=True)
        if not pos:break
        end=f"{pos}+{len(q)}c"; text.tag_add("find",pos,end); pos=end
    def replace():
      q=findvar.get(); r=replacevar.get()
      if not q:return
      pos="1.0"
      while True:
        pos=text.search(q,pos,stopindex="end",nocase=True)
        if not pos:break
        end=f"{pos}+{len(q)}c"; text.delete(pos,end); text.insert(pos,r); pos=f"{pos}+{len(r)}c"
    def save_as():
      path=self._save([("NEXUS Word","*.nexusdoc"),("DOCX","*.docx"),("Text","*.txt")])
      if not path:return
      self._save_word(path); pathvar.set(path)
    def save():
      if not self.word_path:return save_as()
      self._save_word(self.word_path); pathvar.set(self.word_path)
    def open_doc():
      path=self._file([("Word/DOCX","*.docx"),("NEXUS Word","*.nexusdoc"),("Text","*.txt"),("Markdown","*.md")])
      if not path:return
      try:
        content=""
        if path.lower().endswith(".docx"):
          from docx import Document
          d=Document(path); content="\n\n".join(x.text for x in d.paragraphs)
        else: content=Path(path).read_text(encoding="utf-8",errors="replace")
        text.delete("1.0","end"); text.insert("1.0",content); self.word_path=path; pathvar.set(path)
      except Exception as e: messagebox.showerror("NEXUS Word",str(e),parent=self.win)
    def page_break(): text.insert("insert","\n\n"+"─"*70+"\n\n")
    for lab,cmd in [("💾",save),("💾 AS",save_as),("📂",open_doc),("B",lambda:apply("bold")),
                    ("I",lambda:apply("italic")),("U",lambda:apply("underline")),
                    ("TITLE",lambda:apply("title")),("H1",lambda:apply("h1")),("H2",lambda:apply("h2")),
                    ("• LIST",bullet),("↔ L",lambda:set_align("left")),("↔ C",lambda:set_align("center")),
                    ("↔ R",lambda:set_align("right")),("PAGE",page_break)]:
      self.app.btn(toolbar,lab,cmd,THEME["accent_cyan"] if lab in ("💾","💾 AS") else THEME["card"],
                   "#000" if lab in ("💾","💾 AS") else THEME["text"],75,30,9).pack(side="left",padx=2,pady=4)
    findbar=ctk.CTkFrame(f,fg_color=THEME["card"]); findbar.grid(row=2,column=0,sticky="ew",padx=8,pady=(0,8))
    findvar=ctk.StringVar(); replacevar=ctk.StringVar(); pathvar=ctk.StringVar(value="Neues_Dokument.nexusdoc")
    ctk.CTkEntry(findbar,textvariable=findvar,placeholder_text="Suchen…",width=180).pack(side="left",padx=4,pady=5)
    ctk.CTkEntry(findbar,textvariable=replacevar,placeholder_text="Ersetzen…",width=180).pack(side="left",padx=4,pady=5)
    self.app.btn(findbar,"🔎",find,THEME["accent_cyan"],"#000",45,28,9).pack(side="left")
    self.app.btn(findbar,"↻",replace,THEME["accent_green"],"#000",45,28,9).pack(side="left",padx=2)
    ctk.CTkEntry(findbar,textvariable=pathvar).pack(side="right",fill="x",expand=True,padx=5)
    text.insert("1.0","NEXUS Word\n\nBeginne hier mit deinem Dokument…")
    text.tag_add("title","1.0","1.end")
    self.word_path=None

  def _save_word(self,path):
    try:
      text=self.word_text; raw=text.get("1.0","end-1c")
      p=Path(path); p.parent.mkdir(parents=True,exist_ok=True)
      if p.suffix.lower()==".docx":
        from docx import Document
        d=Document()
        for paragraph in raw.split("\n"):
          d.add_paragraph(paragraph)
        d.save(p)
      else: p.write_text(raw,encoding="utf-8")
      self.status.configure(text=f"📝 Gespeichert: {p.name}")
      self.app._office_recent(str(p))
    except Exception as e: self.status.configure(text=f"❌ Word: {e}")

  # ------------------------------ EXCEL ------------------------------
  def excel(self):
    import tkinter as tk
    from tkinter import messagebox
    f=self.clear("📊 NEXUS EXCEL")
    f.pack(fill="both",expand=True); f.grid_rowconfigure(1,weight=1); f.grid_columnconfigure(0,weight=1)
    top=ctk.CTkFrame(f,fg_color=THEME["card"]); top.grid(row=0,column=0,sticky="ew",padx=8,pady=8)
    self.excel_data={"Sheet1":[["" for _ in range(12)] for __ in range(30)]}
    self.excel_sheet="Sheet1"; self.excel_entries={}; self.excel_frame=None
    sheetvar=ctk.StringVar(value="Sheet1")
    def rebuild():
      if self.excel_frame:
        self.excel_frame.destroy()
      outer=ctk.CTkFrame(f,fg_color="#050505"); outer.grid(row=1,column=0,sticky="nsew",padx=8,pady=(0,8))
      outer.grid_rowconfigure(0,weight=1); outer.grid_columnconfigure(0,weight=1)
      canvas=tk.Canvas(outer,bg="#080808",highlightthickness=0)
      sx=ctk.CTkScrollbar(outer,orientation="horizontal",command=canvas.xview); sy=ctk.CTkScrollbar(outer,command=canvas.yview)
      canvas.configure(xscrollcommand=sx.set,yscrollcommand=sy.set)
      canvas.grid(row=0,column=0,sticky="nsew"); sy.grid(row=0,column=1,sticky="ns"); sx.grid(row=1,column=0,sticky="ew")
      inner=tk.Frame(canvas,bg="#080808"); canvas.create_window((0,0),window=inner,anchor="nw")
      self.excel_entries={}
      data=self.excel_data[self.excel_sheet]
      for r in range(len(data)):
        tk.Label(inner,text=str(r+1),bg="#151515",fg="#aaa",width=5).grid(row=r,column=0,sticky="nsew")
        for c in range(len(data[r])):
          letter=self._excel_col(c)
          e=tk.Entry(inner,bg="#0c0c0c",fg="#eee",insertbackground="#00ff88",relief="solid",bd=1,width=14)
          e.grid(row=r,column=c+1,sticky="nsew")
          e.insert(0,str(data[r][c]))
          e.bind("<FocusOut>",lambda ev:self._excel_sync())
          e.bind("<Return>",lambda ev:self._excel_sync())
          self.excel_entries[(r,c)]=e
      for c in range(len(data[0])):
        tk.Label(inner,text=self._excel_col(c),bg="#151515",fg="#00e5ff",width=14).grid(row=-1,column=c+1)
      inner.update_idletasks(); canvas.configure(scrollregion=canvas.bbox("all"))
      self.excel_frame=outer
    def add_sheet():
      name=f"Sheet{len(self.excel_data)+1}"
      self.excel_data[name]=[["" for _ in range(12)] for __ in range(30)]
      sheetvar.set(name); self.excel_sheet=name; rebuild(); sheets.configure(values=list(self.excel_data))
    def select(name):
      self._excel_sync(); self.excel_sheet=name; rebuild()
    def save_xlsx():
      self._excel_sync()
      path=self._save([("Excel","*.xlsx"),("CSV","*.csv"),("NEXUS Excel","*.nexusxlsx")])
      if not path:return
      try:
        if path.lower().endswith(".csv"):
          import csv
          with open(path,"w",newline="",encoding="utf-8-sig") as fh: csv.writer(fh).writerows(self.excel_data[self.excel_sheet])
        elif path.lower().endswith(".nexusxlsx"):
          self._nexus_json_save(path,{"sheets":self.excel_data})
        else:
          from openpyxl import Workbook
          wb=Workbook(); ws=wb.active; ws.title=self.excel_sheet
          for r,row in enumerate(self.excel_data[self.excel_sheet],1):
            for c,val in enumerate(row,1): ws.cell(r,c,value=val)
          for name,data in list(self.excel_data.items())[1:]:
            ws=wb.create_sheet(name)
            for r,row in enumerate(data,1):
              for c,val in enumerate(row,1): ws.cell(r,c,value=val)
          wb.save(path)
        self.status.configure(text=f"📊 Gespeichert: {Path(path).name}")
      except Exception as e: messagebox.showerror("NEXUS Excel",str(e),parent=self.win)
    def open_xlsx():
      path=self._file([("Excel","*.xlsx"),("CSV","*.csv"),("NEXUS Excel","*.nexusxlsx")])
      if not path:return
      try:
        if path.lower().endswith(".csv"):
          import csv
          with open(path,encoding="utf-8-sig",newline="") as fh: rows=list(csv.reader(fh))
          self.excel_data={"Sheet1":[list(r) for r in rows] or [[""]]}
        elif path.lower().endswith(".nexusxlsx"):
          self.excel_data=self._nexus_json_load(path).get("sheets",{"Sheet1":[[""]]})
        else:
          from openpyxl import load_workbook
          wb=load_workbook(path,data_only=False); self.excel_data={}
          for ws in wb.worksheets:
            self.excel_data[ws.title]=[[ws.cell(r,c).value or "" for c in range(1,ws.max_column+1)] for r in range(1,ws.max_row+1)]
        self.excel_sheet=next(iter(self.excel_data)); sheetvar.set(self.excel_sheet); sheets.configure(values=list(self.excel_data)); rebuild()
      except Exception as e: messagebox.showerror("NEXUS Excel",str(e),parent=self.win)
    ctk.CTkLabel(top,text="Tabelle",text_color=THEME["accent_cyan"]).pack(side="left",padx=6)
    sheets=ctk.CTkOptionMenu(top,variable=sheetvar,values=list(self.excel_data),command=select,width=130); sheets.pack(side="left",padx=4)
    self.app.btn(top,"＋ SHEET",add_sheet,THEME["accent_green"],"#000",95,30,9).pack(side="left",padx=3)
    self.app.btn(top,"📂 ÖFFNEN",open_xlsx,THEME["accent_cyan"],"#000",95,30,9).pack(side="left",padx=3)
    self.app.btn(top,"💾 SPEICHERN",save_xlsx,THEME["accent_green"],"#000",110,30,9).pack(side="left",padx=3)
    self.app.btn(top,"Σ FORMEL",lambda:self._excel_formula_dialog(),THEME["accent_purple"],"#fff",100,30,9).pack(side="left",padx=3)
    ctk.CTkLabel(top,text="Formeln: =A1+B1, =SUM(A1:A5), =AVERAGE(B1:B5), =MIN/MAX",font=("Consolas",10),text_color=THEME["subtext"]).pack(side="left",padx=8)
    rebuild()

  def _excel_col(self,n):
    s=""
    while True:
      n,r=divmod(n,26); s=chr(65+r)+s
      if n==0:return s
      n-=1

  def _excel_sync(self):
    try:
      for (r,c),e in self.excel_entries.items():
        self.excel_data[self.excel_sheet][r][c]=e.get()
    except Exception: pass

  def _excel_cell_value(self, sheet, ref, seen=None):
    import ast
    seen=seen or set()
    m=re.fullmatch(r"([A-Z]+)([0-9]+)", ref.upper())
    if not m:return 0.0
    col=0
    for ch in m.group(1): col=col*26+(ord(ch)-64)
    r=int(m.group(2))-1; c=col-1
    data=self.excel_data.get(sheet,[[] for _ in range(30)])
    if r<0 or c<0 or r>=len(data) or c>=len(data[r]):return 0.0
    value=data[r][c]
    if not isinstance(value,str) or not value.startswith("="):
      try:return float(str(value).replace(",","."))
      except Exception:return 0.0
    key=f"{sheet}!{ref}"
    if key in seen:return 0.0
    seen.add(key)
    return self._excel_eval_formula(sheet,value[1:],seen)

  def _excel_eval_formula(self, sheet, formula, seen=None):
    import ast
    seen=seen or set()
    def rng(a,b):
      ma=re.fullmatch(r"([A-Z]+)([0-9]+)",a.upper()); mb=re.fullmatch(r"([A-Z]+)([0-9]+)",b.upper())
      if not ma or not mb:return []
      def ci(s):
        n=0
        for ch in s:n=n*26+ord(ch)-64
        return n-1
      c1,c2=ci(ma.group(1)),ci(mb.group(1)); r1,r2=int(ma.group(2))-1,int(mb.group(2))-1
      return [self._excel_cell_value(sheet,self._excel_col(c)+str(r+1),seen) for r in range(min(r1,r2),max(r1,r2)+1) for c in range(min(c1,c2),max(c1,c2)+1)]
    funcs={}
    for name in ("SUM","AVERAGE","MIN","MAX"):
      funcs[name]=name
    def repl_func(m):
      name=m.group(1).upper(); args=m.group(2)
      vals=[]
      for part in args.split(","):
        part=part.strip()
        if ":" in part:
          a,b=part.split(":",1); vals.extend(rng(a.strip(),b.strip()))
        else:
          vals.append(self._excel_cell_value(sheet,part,seen))
      if name=="SUM":return str(sum(vals))
      if name=="AVERAGE":return str(sum(vals)/len(vals) if vals else 0)
      if name=="MIN":return str(min(vals) if vals else 0)
      return str(max(vals) if vals else 0)
    formula=re.sub(r"\b(SUM|AVERAGE|MIN|MAX)\(([^()]*)\)",repl_func,formula,flags=re.I)
    formula=re.sub(r"\b([A-Z]+[0-9]+)\b",lambda m:str(self._excel_cell_value(sheet,m.group(1),seen)),formula,flags=re.I)
    try:
      node=ast.parse(formula,mode="eval").body
      def ev(n):
        if isinstance(n,ast.Constant) and isinstance(n.value,(int,float)):return n.value
        if isinstance(n,ast.BinOp) and type(n.op) in (ast.Add,ast.Sub,ast.Mult,ast.Div,ast.Pow,ast.Mod):
          a,b=ev(n.left),ev(n.right)
          if isinstance(n.op,ast.Add):return a+b
          if isinstance(n.op,ast.Sub):return a-b
          if isinstance(n.op,ast.Mult):return a*b
          if isinstance(n.op,ast.Div):return a/b if b else 0
          if isinstance(n.op,ast.Pow):return a**b
          return a%b if b else 0
        if isinstance(n,ast.UnaryOp) and type(n.op) in (ast.UAdd,ast.USub):
          return ev(n.operand) if isinstance(n.op,ast.UAdd) else -ev(n.operand)
        raise ValueError("unsichere Formel")
      return ev(node)
    except Exception:return 0.0

  def _excel_formula_dialog(self):
    from tkinter import messagebox
    self._excel_sync()
    if not self.excel_entries:return
    val=self._excel_cell_value(self.excel_sheet,"A1")
    raw=self.excel_data[self.excel_sheet][0][0]
    messagebox.showinfo("NEXUS Excel",f"A1: {raw}\nBerechneter Wert: {val}\n\nUnterstützt:\n=A1+B1\n=SUM(A1:A5)\n=AVERAGE(B1:B5)\n=MIN/MAX(...)",parent=self.win)

  # ------------------------------ PRESENTATION ------------------------------
  def presentation(self):
    from tkinter import filedialog, messagebox
    f=self.clear("🎞️ NEXUS PRESENTATION")
    f.pack(fill="both",expand=True); f.grid_columnconfigure(1,weight=1); f.grid_rowconfigure(0,weight=1)
    left=ctk.CTkFrame(f,fg_color=THEME["card"]); left.grid(row=0,column=0,sticky="ns",padx=8,pady=8)
    right=ctk.CTkFrame(f,fg_color="#080808"); right.grid(row=0,column=1,sticky="nsew",padx=(0,8),pady=8)
    right.grid_rowconfigure(1,weight=1); right.grid_columnconfigure(0,weight=1)
    self.slides=[{"title":"NEXUS Präsentation","body":"Erste Folie"}]; self.slide_index=0
    listbox=tk.Listbox(left,bg="#050505",fg="#00ff88",width=28,selectmode="browse")
    listbox.pack(fill="both",expand=True,padx=6,pady=6)
    def refresh():
      listbox.delete(0,"end")
      for i,s in enumerate(self.slides): listbox.insert("end",f"{i+1}. {s['title'][:28]}")
      listbox.selection_set(self.slide_index); load()
    def load():
      s=self.slides[self.slide_index]; title.delete("1.0","end"); title.insert("1.0",s["title"]); body.delete("1.0","end"); body.insert("1.0",s["body"])
    def sync():
      self.slides[self.slide_index]={"title":title.get("1.0","end-1c"),"body":body.get("1.0","end-1c"),**{k:v for k,v in self.slides[self.slide_index].items() if k not in ("title","body")}}
    def add():
      sync(); self.slides.append({"title":f"Folie {len(self.slides)+1}","body":""}); self.slide_index=len(self.slides)-1; refresh()
    def delete():
      if len(self.slides)==1:return
      self.slides.pop(self.slide_index); self.slide_index=max(0,self.slide_index-1); refresh()
    def select(ev):
      sync(); sel=listbox.curselection()
      if sel:self.slide_index=sel[0]; load()
    listbox.bind("<<ListboxSelect>>",select)
    self.app.btn(left,"＋ FOLIE",add,THEME["accent_green"],"#000",170,35,10).pack(pady=3)
    self.app.btn(left,"− LÖSCHEN",delete,THEME["accent_pink"],"#fff",170,35,10).pack(pady=3)
    self.app.btn(left,"📤 PPTX EXPORT",lambda:self._pptx_export(),THEME["accent_cyan"],"#000",170,35,10).pack(pady=3)
    self.app.btn(left,"▶ PRÄSENTATION",lambda:self._present_slides(),THEME["accent_purple"],"#fff",170,35,10).pack(pady=3)
    bar=ctk.CTkFrame(right,fg_color=THEME["card"]); bar.grid(row=0,column=0,sticky="ew",padx=8,pady=8)
    self.app.btn(bar,"💾",lambda:self._nexus_json_save_dialog("presentation",self.slides),THEME["accent_green"],"#000",55,30,9).pack(side="left")
    self.app.btn(bar,"📂",lambda:self._nexus_json_open_dialog("presentation",self.slides),THEME["accent_cyan"],"#000",55,30,9).pack(side="left",padx=3)
    title=ctk.CTkTextbox(right,height=80,fg_color="#111",font=("Arial",24,"bold")); title.grid(row=1,column=0,sticky="new",padx=25,pady=(20,8))
    body=ctk.CTkTextbox(right,fg_color="#111",font=("Arial",14)); body.grid(row=2,column=0,sticky="nsew",padx=25,pady=8)
    refresh()

  def _pptx_export(self):
    from tkinter import messagebox
    path=self._save([("PowerPoint","*.pptx")])
    if not path:return
    try:
      from pptx import Presentation
      from pptx.util import Inches,Pt
      prs=Presentation()
      for i,s in enumerate(self.slides):
        slide=prs.slides[0] if i==0 else prs.slides.add_slide(prs.slide_layouts[5])
        if i==0 and len(prs.slides)==1:
          pass
        tx=slide.shapes.add_textbox(Inches(1),Inches(.7),Inches(11),Inches(1.2)).text_frame
        tx.text=s["title"]; tx.paragraphs[0].font.size=Pt(28)
        bx=slide.shapes.add_textbox(Inches(1),Inches(2),Inches(11),Inches(5)).text_frame
        bx.text=s["body"]; bx.paragraphs[0].font.size=Pt(18)
      prs.save(path); self.status.configure(text=f"🎞️ PPTX: {Path(path).name}")
    except Exception as e: messagebox.showerror("PPTX",str(e),parent=self.win)

  def _present_slides(self):
    import tkinter as tk
    w=tk.Toplevel(self.win); w.title("NEXUS PRESENTATION MODE"); w.configure(bg="#000")
    w.attributes("-fullscreen",True); w.bind("<Escape>",lambda e:w.destroy())
    idx=[0]; lbl=tk.Label(w,bg="#000",fg="#fff",font=("Arial",34),justify="left",anchor="nw",padx=90,pady=70)
    lbl.pack(fill="both",expand=True)
    def show():
      s=self.slides[idx[0]]; lbl.configure(text=s["title"]+"\n\n"+s["body"])
    w.bind("<Right>",lambda e:(idx.__setitem__(0,min(len(self.slides)-1,idx[0]+1)),show()))
    w.bind("<Left>",lambda e:(idx.__setitem__(0,max(0,idx[0]-1)),show()))
    show()

  # ------------------------------ PDF ------------------------------
  def pdf_tools(self):
    from tkinter import messagebox, filedialog
    f=self.clear("📄 NEXUS PDF")
    f.pack(fill="both",expand=True)
    ctk.CTkLabel(f,text="PDF WORKSPACE",font=("Consolas",22,"bold"),text_color=THEME["accent_cyan"]).pack(pady=20)
    out=ctk.CTkTextbox(f,fg_color="#050505",font=("Consolas",12)); out.pack(fill="both",expand=True,padx=20,pady=10)
    def info():
      path=self._file([("PDF","*.pdf")])
      if not path:return
      try:
        import fitz
        d=fitz.open(path); out.delete("1.0","end")
        out.insert("1.0",f"{Path(path).name}\nSeiten: {len(d)}\n\n")
        for i,p in enumerate(d):
          out.insert("end",f"--- Seite {i+1} ---\n{p.get_text()[:3000]}\n\n")
      except Exception as e: messagebox.showerror("PDF",str(e),parent=self.win)
    def merge():
      paths=filedialog.askopenfilenames(parent=self.win,filetypes=[("PDF","*.pdf")])
      if not paths:return
      dest=self._save([("PDF","*.pdf")])
      if not dest:return
      try:
        import fitz
        outdoc=fitz.open()
        for x in paths: outdoc.insert_pdf(fitz.open(x))
        outdoc.save(dest); outdoc.close(); self.status.configure(text="📄 PDF zusammengeführt")
      except Exception as e: messagebox.showerror("PDF",str(e),parent=self.win)
    for lab,fn,col in [("📖 ÖFFNEN / TEXT",info,THEME["accent_cyan"]),("🔗 PDF ZUSAMMENFÜHREN",merge,THEME["accent_green"])]:
      self.app.btn(f,lab,fn,col,"#000",220,40,11).pack(pady=7)

  # ------------------------------ NOTES / TASKS / CALENDAR ------------------------------
  def notes(self):
    f=self.clear("📒 NEXUS NOTES"); f.pack(fill="both",expand=True)
    self.notes_text=self._text_area(f)
    path=Path(self.app.nexus_paths["documents"])/"NEXUS_Notes.nexusnote"
    try:self.notes_text.insert("1.0",path.read_text(encoding="utf-8"))
    except Exception:self.notes_text.insert("1.0","# NEXUS NOTES\n\n")
    bar=ctk.CTkFrame(f,fg_color=THEME["card"]); bar.pack(fill="x",padx=8,pady=5)
    self.app.btn(bar,"💾 SPEICHERN",lambda:path.write_text(self.notes_text.get("1.0","end-1c"),encoding="utf-8"),
                 THEME["accent_green"],"#000",120,32,10).pack(side="right")

  def tasks(self):
    f=self.clear("✅ NEXUS TASKS"); f.pack(fill="both",expand=True)
    self.tasks_data=self._nexus_json_load(str(Path(self.app.nexus_paths["school"])/"tasks.json")) if Path(Path(self.app.nexus_paths["school"])/"tasks.json").exists() else {"tasks":[]}
    top=ctk.CTkFrame(f,fg_color=THEME["card"]); top.pack(fill="x",padx=8,pady=8)
    ent=ctk.CTkEntry(top,placeholder_text="Neue Aufgabe…",width=500); ent.pack(side="left",padx=5,pady=8)
    due=ctk.CTkEntry(top,placeholder_text="Fällig: YYYY-MM-DD",width=160); due.pack(side="left",padx=5)
    listbox=ctk.CTkScrollableFrame(f,fg_color="#050505"); listbox.pack(fill="both",expand=True,padx=8,pady=8)
    def save():
      self._nexus_json_save(str(Path(self.app.nexus_paths["school"])/"tasks.json"),self.tasks_data)
    def render():
      for w in listbox.winfo_children():w.destroy()
      for i,t in enumerate(self.tasks_data["tasks"]):
        row=ctk.CTkFrame(listbox,fg_color=THEME["card"]); row.pack(fill="x",pady=3)
        done=ctk.BooleanVar(value=t.get("done",False))
        ctk.CTkCheckBox(row,text=t["text"],variable=done,command=lambda i=i,v=done:self._task_toggle(i,v,render,save)).pack(side="left",padx=8,pady=8)
        ctk.CTkLabel(row,text=t.get("due",""),text_color=THEME["subtext"]).pack(side="right",padx=8)
    def add():
      if ent.get().strip():
        self.tasks_data["tasks"].append({"text":ent.get().strip(),"due":due.get().strip(),"done":False});ent.delete(0,"end");due.delete(0,"end");save();render()
    self.app.btn(top,"＋",add,THEME["accent_green"],"#000",50,32,10).pack(side="left")
    render()

  def _task_toggle(self,i,var,render,save):
    self.tasks_data["tasks"][i]["done"]=bool(var.get());save();render()

  def calendar(self):
    f=self.clear("📅 NEXUS KALENDER"); f.pack(fill="both",expand=True)
