  def mail(self):
    f=self.clear("✉️ NEXUS MAIL"); f.pack(fill="both",expand=True); f.grid_columnconfigure(0,weight=1);f.grid_rowconfigure(1,weight=1)
    bar=ctk.CTkFrame(f,fg_color=THEME["card"]);bar.grid(row=0,column=0,sticky="ew",padx=8,pady=8)
