    self.app.btn(bottom,"💾 ENTWURF",lambda:self._mail_draft(account.get(),to.get(),subj.get(),body.get("1.0","end-1c")),
                 THEME["accent_cyan"],"#000",130,34,10).pack(side="left",padx=4)
