def _nxo_excel_eval_formula(self, sheet, formula, seen=None):
  import ast, re
  seen=seen or set(); formula=str(formula).strip()
  def ref_parts(ref):
    m=re.fullmatch(r"([A-Z]+)([0-9]+)",str(ref).upper())
    if not m:return None
    col=0
    for ch in m.group(1):col=col*26+ord(ch)-64
    return int(m.group(2))-1,col-1
  def rng(a,b):
    pa,pb=ref_parts(a),ref_parts(b)
    if not pa or not pb:return []
    r1,c1=pa;r2,c2=pb;out=[]
    for r in range(min(r1,r2),max(r1,r2)+1):
      for c in range(min(c1,c2),max(c1,c2)+1):out.append(self._excel_cell_value(sheet,self._excel_col(c)+str(r+1),seen))
    return out
  def split_args(s):
    parts=[];start=0;depth=0;quote=None
    for i,ch in enumerate(s):
      if ch in "\"'":quote=None if quote==ch else (ch if quote is None else quote)
      elif quote is None and ch=='(':depth+=1
      elif quote is None and ch==')':depth-=1
      elif quote is None and ch==',' and depth==0:parts.append(s[start:i].strip());start=i+1
    parts.append(s[start:].strip());return parts
  def eval_atom(x):
    x=x.strip()
    if ':' in x and re.fullmatch(r'[A-Z]+[0-9]+:[A-Z]+[0-9]+',x.upper()):return rng(*x.split(':',1))
    if re.fullmatch(r'[A-Z]+[0-9]+',x.upper()):return self._excel_cell_value(sheet,x.upper(),seen)
    if len(x)>=2 and x[0]==x[-1] and x[0] in "\"'":return x[1:-1]
    try:return float(x.replace(',','.'))
    except Exception:return x
  def expand_functions(expr):
    pattern=re.compile(r'\b(SUM|AVERAGE|MIN|MAX|COUNT|COUNTA|ABS|ROUND|IF)\s*\(',re.I)
    while True:
      m=pattern.search(expr)
      if not m:break
      name=m.group(1).upper();open_i=expr.find('(',m.start());depth=0;quote=None;close_i=None
      for j in range(open_i,len(expr)):
        ch=expr[j]
        if ch in "\"'":quote=None if quote==ch else (ch if quote is None else quote)
        elif quote is None and ch=='(':depth+=1
        elif quote is None and ch==')':
          depth-=1
          if depth==0:close_i=j;break
      if close_i is None:break
      args=split_args(expr[open_i+1:close_i]);vals=[]
      for a in args:
        v=eval_atom(a);vals.extend(v if isinstance(v,list) else [v])
      nums=[float(v) for v in vals if isinstance(v,(int,float)) or (isinstance(v,str) and re.fullmatch(r'-?\d+(?:\.\d+)?',v.strip() or ''))]
      if name=='SUM':val=sum(nums)
      elif name=='AVERAGE':val=sum(nums)/len(nums) if nums else 0
      elif name=='MIN':val=min(nums) if nums else 0
      elif name=='MAX':val=max(nums) if nums else 0
      elif name=='COUNT':val=len(nums)
      elif name=='COUNTA':val=sum(1 for v in vals if str(v).strip()!='')
      elif name=='ABS':val=abs(float(vals[0])) if vals else 0
      elif name=='ROUND':val=round(float(vals[0]),int(float(vals[1]))) if vals else 0
      elif name=='IF':
        cond=str(args[0]) if args else ''
        cond=re.sub(r'\b([A-Z]+[0-9]+)\b',lambda mm:str(self._excel_cell_value(sheet,mm.group(1),seen)),cond,flags=re.I)
        cond=cond.replace('<>','!=').replace('=','==')
        try:ok=bool(eval(cond,{'__builtins__':{}},{}))
        except Exception:ok=False
        val=eval_atom(args[1] if len(args)>1 and ok else (args[2] if len(args)>2 else '0'))
      else:val=0
      expr=expr[:m.start()]+str(val)+expr[close_i+1:]
    return expr
  formula=expand_functions(formula)
  formula=re.sub(r'\b([A-Z]+[0-9]+)\b',lambda m:str(self._excel_cell_value(sheet,m.group(1),seen)),formula,flags=re.I)
  formula=formula.replace('^','**').replace('<>','!=')
  formula=re.sub(r'(?<![<>!=])=(?!=)','==',formula)
  try:
    node=__import__('ast').parse(formula,mode='eval').body
    allowed=(ast.Expression,ast.Constant,ast.BinOp,ast.UnaryOp,ast.Add,ast.Sub,ast.Mult,ast.Div,ast.Pow,ast.Mod,ast.UAdd,ast.USub,ast.Compare,ast.Eq,ast.NotEq,ast.Lt,ast.LtE,ast.Gt,ast.GtE,ast.BoolOp,ast.And,ast.Or,ast.Name)
    if any(not isinstance(n,allowed) for n in ast.walk(node)):raise ValueError('unsichere Formel')
    return eval(compile(ast.Expression(node),'','eval'),{'__builtins__':{}},{'True':True,'False':False})
  except Exception:return 0.0
NEXUSOfficeSuite._excel_eval_formula=_nxo_excel_eval_formula

# Main NEXUS navigation now opens the real Office Ultra suite instead of the
# former placeholder window.
def _nxo_app_open_office(self):
  try:
    suite=getattr(self,"_office_suite",None)
    if suite is None:
      suite=NEXUSOfficeSuite(self);self._office_suite=suite
    else:
      suite._open_window()
  except Exception as e:
    try:self._game_log(f"Office Ultra: {e}")
    except Exception:pass
    try:messagebox.showerror("NEXUS Office Ultra",f"Office konnte nicht geöffnet werden:\n{e}")
    except Exception:pass
AppExtension._nexus_open_office=_nxo_app_open_office

# Replace the old generator wrapper with a direct, reliable launcher.
def _nxo_b_office(self):
  v=self.views["office"];v.grid_columnconfigure(0,weight=1);v.grid_rowconfigure(0,weight=1)
  for w in v.winfo_children():w.destroy()
  f=ctk.CTkFrame(v,fg_color=THEME["card"],border_color=THEME["accent_cyan"],border_width=1);f.grid(row=0,column=0,sticky="nsew",padx=30,pady=30)
  ctk.CTkLabel(f,text="⬡ NEXUS SCHOOL + OFFICE ULTRA",font=("Consolas",28,"bold"),text_color=THEME["accent_cyan"]).pack(pady=(55,10))
