  self.btn(f,"🚀 OFFICE ULTRA ÖFFNEN",self._nexus_open_office,THEME["accent_green"],"#000",310,56,14).pack(pady=28)
  row=ctk.CTkFrame(f,fg_color="transparent");row.pack()
  for lab,fn,col in [("📝 Word",lambda:self._nexus_open_office(),THEME["accent_cyan"]),("📊 Excel",lambda:self._nexus_open_office(),THEME["accent_green"]),("🎞️ PPT",lambda:self._nexus_open_office(),THEME["accent_purple"]),("📄 PDF",lambda:self._nexus_open_office(),THEME["accent_cyan"]),("🤖 KI",lambda:self._nexus_open_domain_ai("office"),THEME["accent_green"])]:self.btn(row,lab,fn,col,"#000" if col!=THEME["accent_purple"] else "#fff",105,36,9).pack(side="left",padx=4)
  ctk.CTkLabel(f,text="Offline-first • Dateien bleiben auf deinem PC • keine Office-Cloud nötig",font=("Consolas",11),text_color=THEME["subtext"]).pack(pady=25)
