def _nexus_help_text_for_widget(w):
  import tkinter as _tk
  parts=[]
  try:
    for key in ("text", "placeholder_text", "label_text"):
      try:
        val=w.cget(key)
        if val: parts.append(str(val))
      except Exception: pass
  except Exception: pass
  try:
    vals=w.cget("values")
    if vals: parts.append("Optionen: " + ", ".join(map(str, vals)))
  except Exception: pass
  try:
    var=w.cget("variable")
    if var:
      val=var.get()
      if val: parts.append(str(val))
  except Exception: pass
  label=" ".join(parts).strip()
  low=label.lower()
  # Specific selected values first, so profile and quality options get meaningful help.
  for key, desc in _NEXUS_HELP_EXACT.items():
    if low == key or low.endswith(" " + key): return desc
  for keys, desc in _NEXUS_HELP_KEYWORDS:
    if any(k in low for k in keys):
      # Dropdowns include their available choices and short general guidance.
      try:
        vals=w.cget("values")
        if vals:
          unique=[]
          for val in vals:
            sv=str(val); expl=_NEXUS_HELP_EXACT.get(sv.lower())
            if expl: unique.append(f"{sv}: {expl}")
            else: unique.append(sv)
          if unique: return desc + "\n\nVerfügbare Auswahl:\n• " + "\n• ".join(unique[:8])
      except Exception: pass
      return desc
  # Explain each individual checkbox/switch/radio/button even when a module-specific map is absent.
  cname=type(w).__name__.lower()
  if "checkbox" in cname or "switch" in cname or "radio" in cname:
    return (f"Diese Auswahl schaltet eine einzelne Funktion um oder wählt eine Variante aus. "
            f"Aktueller Eintrag: {label or 'Option'}. Wenn du unsicher bist, lasse die Standardeinstellung aktiv.")
  if "optionmenu" in cname or "combobox" in cname or "segmented" in cname:
    try:
      vals=w.cget("values")
      if vals: return "Wähle die passende Variante für deinen Anwendungsfall.\n\nOptionen: " + ", ".join(map(str, vals[:10])) + ". Bei Unsicherheit ist die Standardauswahl der beste Startpunkt."
    except Exception: pass
    return "Öffne diese Auswahl und wähle die Einstellung, die zu deinem Ziel passt. Die Auswahl kann beeinflussen, wie schnell oder in welcher Qualität das Ergebnis erstellt wird."
  if "slider" in cname:
    return "Regler: verschiebe den Wert schrittweise. Ändere zunächst wenig und vergleiche anschließend das Ergebnis, damit du die Wirkung erkennst."
  if "button" in cname:
    return f"Aktion: {label or 'führt eine Funktion aus'}. NEXUS sollte das Ergebnis im Status oder Protokoll bestätigen; ein Klick allein beweist noch keinen Erfolg."
  if label:
    return f"Einstellung/Funktion: {label}. Hier kannst du den zugehörigen Bereich steuern. Wenn du die Wirkung nicht kennst, ändere die Standardeinstellung zunächst nicht."
  return None

def _nexus_tooltip_show(self, widget):
  try:
    if not widget.winfo_exists(): return
    text=_nexus_help_text_for_widget(widget)
    if not text: return
    self._nexus_tooltip_hide()
    x=widget.winfo_rootx()+min(max(widget.winfo_width()//2,10),300)
    y=widget.winfo_rooty()+widget.winfo_height()+8
    tip=tk.Toplevel(self)
    tip.wm_overrideredirect(True)
    try: tip.attributes("-topmost", True)
    except Exception: pass
    tip.configure(bg="#0B1422")
    frame=tk.Frame(tip,bg="#0B1422",highlightbackground="#67E8F9",highlightthickness=1,bd=0)
    frame.pack(fill="both",expand=True)
    tk.Label(frame,text="NEXUS  ·  KURZHILFE",bg="#0B1422",fg="#67E8F9",font=("Segoe UI",9,"bold"),anchor="w").pack(fill="x",padx=10,pady=(8,2))
    tk.Label(frame,text=text,bg="#0B1422",fg="#F3F6FC",font=("Segoe UI",10),justify="left",anchor="w",wraplength=350).pack(fill="both",padx=10,pady=(0,9))
    tip.update_idletasks()
    sw,sh=tip.winfo_screenwidth(),tip.winfo_screenheight()
    tw,th=tip.winfo_reqwidth(),tip.winfo_reqheight()
    x=max(8,min(x,sw-tw-8)); y=max(8,min(y,sh-th-8))
    tip.geometry(f"+{x}+{y}")
    self._nexus_tooltip_window=tip
  except Exception:
    try: self._nexus_tooltip_hide()
    except Exception: pass

def _nexus_tooltip_hide(self):
  try:
    if getattr(self,"_nexus_tooltip_window",None) is not None:
      self._nexus_tooltip_window.destroy()
  except Exception: pass
  self._nexus_tooltip_window=None

def _nexus_tooltip_enter(self, widget, event=None):
  try:
    if getattr(self,"_nexus_tooltip_after",None): self.after_cancel(self._nexus_tooltip_after)
  except Exception: pass
  try: self._nexus_tooltip_after=self.after(520,lambda:self._nexus_tooltip_show(widget))
  except Exception: pass

def _nexus_tooltip_leave(self, widget=None, event=None):
  try:
    if getattr(self,"_nexus_tooltip_after",None): self.after_cancel(self._nexus_tooltip_after)
  except Exception: pass
  self._nexus_tooltip_after=None
  self._nexus_tooltip_hide()

def _nexus_scan_controls(self):
  """Attach explanations to new controls across lazily-built and dynamically-opened modules."""
  try:
    if not self.winfo_exists(): return
    stack=[self]
    while stack:
      parent=stack.pop()
      try: children=parent.winfo_children()
      except Exception: children=[]
      stack.extend(children)
      for w in children:
        try:
          if getattr(w,"_nexus_help_bound",False): continue
          cls=type(w).__name__.lower()
          selectable=any(token in cls for token in ("button","checkbox","switch","radio","optionmenu","combobox","slider","entry","segmentedcontrol"))
          if not selectable: continue
          # Only controls with some semantic label get tooltips; all normal buttons/selectors have one.
          help_text=_nexus_help_text_for_widget(w)
          if not help_text: continue
          w._nexus_help_bound=True
          w.bind("<Enter>",lambda e,ww=w:self._nexus_tooltip_enter(ww,e),add="+")
          w.bind("<Leave>",lambda e,ww=w:self._nexus_tooltip_leave(ww,e),add="+")
          w.bind("<ButtonPress>",lambda e:self._nexus_tooltip_leave(),add="+")
        except Exception: pass
    # Scan again later because most pages are constructed only when opened.
    self._nexus_help_scan_job=self.after(3000,self._nexus_scan_controls)
  except Exception: pass

def _nexus_start_modern_ux(self):
  try:
    self._nexus_tooltip_window=None
    self._nexus_tooltip_after=None
    self._nexus_help_scan_job=None
    self.after(700,self._nexus_scan_controls)
  except Exception: pass

# Install the UX layer on the shared base app so all extensions inherit it.
_App_init_before_modern_ux = App.__init__
def _nexus_app_init_modern_ux(self,*args,**kwargs):
  _App_init_before_modern_ux(self,*args,**kwargs)
  _nexus_start_modern_ux(self)
App.__init__ = _nexus_app_init_modern_ux
App._nexus_tooltip_show = _nexus_tooltip_show
App._nexus_tooltip_hide = _nexus_tooltip_hide
App._nexus_tooltip_enter = _nexus_tooltip_enter
App._nexus_tooltip_leave = _nexus_tooltip_leave
App._nexus_scan_controls = _nexus_scan_controls

# -----------------------------------------------------------------------------
# NEXUS PERFORMANCE LAB • real local diagnostics, no fake FPS/ping values.
# This module observes the system; it does not change Windows settings.
# -----------------------------------------------------------------------------
def _nxperf_collect_report(self):
  import importlib.util as _ilu
  import socket as _socket
  report = {
      "time": datetime.now().astimezone().isoformat(timespec="seconds"),
      "python": sys.version.split()[0],
      "platform": platform.platform(),
      "checks": [],
      "recommendations": [],
  }
  def add(name, status, value, detail=""):
    report["checks"].append({"name": name, "status": status, "value": str(value), "detail": str(detail)})
  # Sample CPU briefly rather than presenting the stale initial psutil value.
  try:
    if psutil:
      cpu = psutil.cpu_percent(interval=0.35)
      vm = psutil.virtual_memory()
      root = Path(os.path.abspath(os.sep))
      du = psutil.disk_usage(str(root))
      add("CPU", "WARN" if cpu >= 90 else "OK", f"{cpu:.0f}% Auslastung", "Kurzzeitmessung über 0,35 Sekunden; Momentaufnahme, kein Benchmark.")
      add("RAM", "WARN" if vm.percent >= 90 else "OK", f"{vm.percent:.0f}% belegt · {vm.available / (1024**3):.1f} GB verfügbar", "Hohe Belegung allein ist kein Grund für aggressives RAM-Leeren.")
      add("Systemlaufwerk", "WARN" if du.percent >= 90 else "OK", f"{du.percent:.0f}% belegt · {du.free / (1024**3):.1f} GB frei", "Wenig freier Speicher kann Updates, Cache und große Medienprojekte beeinträchtigen.")
      try:
        top=[]
        for proc in psutil.process_iter(["name","memory_info"]):
          try:
            mi=proc.info.get("memory_info")
            if mi: top.append((proc.info.get("name") or "?", mi.rss))
          except Exception: pass
        top.sort(key=lambda item:item[1],reverse=True)
        report["top_memory_processes"]=[{"name":n,"memory_mb":round(b/(1024**2))} for n,b in top[:5]]
      except Exception: pass
    else:
      add("Systemwerte", "WARN", "psutil fehlt", "CPU-, RAM- und Laufwerkswerte sind ohne psutil nicht verfügbar.")
  except Exception as e:
    add("Systemwerte", "ERROR", "Messung fehlgeschlagen", e)
  # Check important local runtimes without installing anything or contacting the internet.
  try:
    import shutil as _shutil
    local_ffmpeg=Path(__file__).resolve().parent / "tools" / "ffmpeg" / "bin" / ("ffmpeg.exe" if os.name=="nt" else "ffmpeg")
    ffmpeg=_shutil.which("ffmpeg") or (str(local_ffmpeg) if local_ffmpeg.exists() else None)
    add("FFmpeg", "OK" if ffmpeg else "INFO", ffmpeg or "nicht gefunden", "Wird für Video-/Audioverarbeitung und manche Aufnahmefunktionen benötigt.")
  except Exception as e: add("FFmpeg", "ERROR", "Prüfung fehlgeschlagen", e)
  try:
    packages={"Pillow":"PIL","NumPy":"numpy","OpenCV":"cv2","SoundDevice":"sounddevice","Ollama Python":"ollama"}
    missing=[]
    for label,module in packages.items():
      try: present=_ilu.find_spec(module) is not None
      except Exception: present=False
      if not present: missing.append(label)
    add("Optionale Python-Pakete", "WARN" if missing else "OK", "Fehlen: " + ", ".join(missing) if missing else "Grundpakete gefunden", "Fehlende optionale Pakete können einzelne Medien-/KI-Funktionen deaktivieren; sie werden nicht automatisch installiert.")
  except Exception as e: add("Python-Pakete", "ERROR", "Prüfung fehlgeschlagen", e)
  try:
    req=urllib.request.Request("http://127.0.0.1:11434/api/tags",headers={"User-Agent":"NEXUS-Local-Diagnostics"})
    with urllib.request.urlopen(req,timeout=1.2) as resp:
      data=json.loads(resp.read(1_000_000).decode("utf-8","replace"))
    models=[m.get("name","") for m in data.get("models",[]) if isinstance(m,dict)]
    add("Ollama lokal", "OK", f"erreichbar · {len(models)} Modell(e)", ", ".join(models[:8]) if models else "Dienst erreichbar, aber keine Modelle gemeldet.")
  except Exception:
    add("Ollama lokal", "INFO", "nicht erreichbar", "Lokaler KI-Dienst unter 127.0.0.1:11434 antwortet nicht. Nur relevant, wenn lokale Ollama-Modelle verwendet werden.")
  try:
    with _socket.create_connection(("127.0.0.1",8188),timeout=0.45): comfy=True
    add("ComfyUI", "OK" if comfy else "INFO", "Port 8188 erreichbar", "Lokaler ComfyUI-Port; dies bestätigt nur die TCP-Erreichbarkeit, nicht die Funktionsfähigkeit jedes Workflows.")
  except Exception:
    add("ComfyUI", "INFO", "Port 8188 nicht erreichbar", "ComfyUI läuft möglicherweise nicht. Nur relevant für die lokale Bild-/Video-Generierung.")
  # Best-effort GPU name on Windows; bounded timeout and no visible console.
  try:
    if os.name=="nt":
      flags=getattr(subprocess,"CREATE_NO_WINDOW",0)
      cmd=["powershell","-NoProfile","-NonInteractive","-Command","Get-CimInstance Win32_VideoController | Select-Object -ExpandProperty Name"]
      kwargs={"capture_output":True,"text":True,"encoding":"utf-8","errors":"replace","timeout":5}
      if flags: kwargs["creationflags"]=flags
      p=subprocess.run(cmd,**kwargs)
      gpus=[x.strip() for x in p.stdout.splitlines() if x.strip()] if p.returncode==0 else []
      add("Grafikkarte", "OK" if gpus else "INFO", "; ".join(gpus[:4]) if gpus else "Name nicht ermittelt", "Ermittelt über Windows WMI. Auslastung und FPS werden damit nicht gemessen.")
    else: add("Grafikkarte", "INFO", "automatische Erkennung nur unter Windows", "")
  except Exception as e: add("Grafikkarte", "INFO", "Name nicht ermittelt", e)
  for c in report["checks"]:
    if c["status"] in ("WARN","ERROR"):
      report["recommendations"].append(f'{c["name"]}: {c["detail"] or c["value"]}')
  report["recommendations"].append("Für FPS-Vergleiche dieselbe Spielszene, Auflösung und Grafikoptionen verwenden und FPS/Framezeiten mit einem echten Spiel-Overlay oder Benchmark messen.")
  report["recommendations"].append("Ein Ping-Test zu einem allgemeinen Internetziel ist nicht gleich dem Ping zum Spielserver; für die Latenz zuerst den Server und die Verbindung vergleichen.")
  report["recommendations"].append("Dieses Diagnoseprofil ändert keine Registry-, DNS-, TCP- oder Energieeinstellungen und beendet keine Prozesse.")
  return report

def _nxperf_render_report(self, report, output_widget, status_label):
  try:
    if not output_widget.winfo_exists(): return
    output_widget.configure(state="normal")
    output_widget.delete("1.0","end")
    lines=["NEXUS PERFORMANCE LAB — SYSTEMBERICHT", "="*44, f'Zeit: {report.get("time","-")}', f'Python: {report.get("python","-")}', f'Plattform: {report.get("platform","-")}', ""]
    for c in report.get("checks",[]):
      icon={"OK":"✓","WARN":"!","ERROR":"✕","INFO":"i"}.get(c.get("status"),"•")
      lines.append(f'{icon} {c.get("name")}: {c.get("value")}')
      if c.get("detail"): lines.append(f'    {c["detail"]}')
    top=report.get("top_memory_processes",[])
    if top:
      lines += ["", "PROZESSE MIT DEM MEISTEN ARBEITSSPEICHER"]
      lines += [f'• {p["name"]}: {p["memory_mb"]} MB' for p in top]
    lines += ["", "EMPFEHLUNGEN"]
    lines += [f'• {x}' for x in report.get("recommendations",[])]
    output_widget.insert("1.0","\n".join(lines))
    output_widget.configure(state="disabled")
    errors=sum(1 for c in report.get("checks",[]) if c.get("status") in ("WARN","ERROR"))
    status_label.configure(text=f'Diagnose abgeschlossen · {len(report.get("checks",[]))} Prüfungen · {errors} Hinweis(e)',text_color=THEME["accent_green"] if not errors else THEME["accent_cyan"])
  except Exception as e:
    try: status_label.configure(text=f"Bericht konnte nicht angezeigt werden: {e}",text_color=THEME["accent_red"])
    except Exception: pass

def _nxperf_run_diagnostics(self, output_widget, status_label, run_button):
  try:
    run_button.configure(state="disabled",text="Prüfe System …")
    status_label.configure(text="Lokale Diagnose läuft im Hintergrund. NEXUS bleibt bedienbar …",text_color=THEME["subtext"])
  except Exception: pass
  def worker():
    try: result=_nxperf_collect_report(self)
    except Exception as e: result={"time":datetime.now().isoformat(timespec="seconds"),"python":sys.version.split()[0],"platform":platform.platform(),"checks":[{"name":"Diagnose","status":"ERROR","value":"fehlgeschlagen","detail":str(e)}],"recommendations":[]}
    def finish():
      self._nxperf_last_report=result
      _nxperf_render_report(self,result,output_widget,status_label)
      try: run_button.configure(state="normal",text="⟳ Diagnose erneut ausführen")
      except Exception: pass
    try: self.after(0,finish)
    except Exception: pass
  try: self.ex.submit(worker)
  except Exception:
    threading.Thread(target=worker,daemon=True).start()

def _nxperf_export_report(self):
  report=getattr(self,"_nxperf_last_report",None)
  if not report:
    try: messagebox.showinfo("NEXUS Performance Lab","Führe zuerst eine Diagnose aus.",parent=self)
    except Exception: pass
    return
  try:
    base=Path(__file__).resolve().parent / "reports"
    base.mkdir(parents=True,exist_ok=True)
    path=base / ("nexus_diagnose_"+datetime.now().strftime("%Y%m%d_%H%M%S")+".json")
    path.write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding="utf-8")
    try: messagebox.showinfo("NEXUS Performance Lab",f"Bericht gespeichert:\n{path}",parent=self)
    except Exception: pass
  except Exception as e:
    try: messagebox.showerror("NEXUS Performance Lab",f"Bericht konnte nicht gespeichert werden:\n{e}",parent=self)
    except Exception: pass

def _nxperf_open_reports(self):
  try:
    path=Path(__file__).resolve().parent / "reports"
    path.mkdir(parents=True,exist_ok=True)
    if os.name=="nt": os.startfile(str(path))
    elif sys.platform=="darwin": subprocess.Popen(["open",str(path)])
    else: subprocess.Popen(["xdg-open",str(path)])
  except Exception as e:
    try: messagebox.showerror("NEXUS Performance Lab",str(e),parent=self)
    except Exception: pass

def _nxperf_builder(self):
  v=self.views["performance_lab"]
  v.grid_columnconfigure(0,weight=1); v.grid_rowconfigure(2,weight=1)
  head=ctk.CTkFrame(v,fg_color=THEME["card"],border_color=THEME["accent_cyan"],border_width=1,corner_radius=14)
  head.grid(row=0,column=0,sticky="ew",padx=16,pady=(14,8))
  ctk.CTkLabel(head,text="🧪 NEXUS PERFORMANCE LAB",font=("Segoe UI",22,"bold"),text_color=THEME["text"]).pack(anchor="w",padx=18,pady=(14,3))
  ctk.CTkLabel(head,text="Echte lokale Diagnose · keine erfundenen FPS · keine automatischen Systemänderungen",font=("Segoe UI",12),text_color=THEME["subtext"],wraplength=1000,justify="left").pack(anchor="w",padx=18,pady=(0,14))
  row=ctk.CTkFrame(v,fg_color="transparent"); row.grid(row=1,column=0,sticky="ew",padx=16,pady=5)
  status=ctk.CTkLabel(row,text="Noch keine Diagnose ausgeführt",font=("Segoe UI",12),text_color=THEME["subtext"],anchor="w")
  status.pack(side="left",fill="x",expand=True,padx=(0,8))
  run=ctk.CTkButton(row,text="▶ Diagnose ausführen",height=38,fg_color=THEME["accent_cyan"],hover_color=THEME["accent_blue"],text_color="#07111b",font=("Segoe UI",12,"bold"))
  run.pack(side="right",padx=3)
  ctk.CTkButton(row,text="Bericht exportieren",command=self._nxperf_export_report,height=38,fg_color=THEME["card2"],hover_color=THEME["border2"],text_color=THEME["text"]).pack(side="right",padx=3)
  ctk.CTkButton(row,text="Berichte öffnen",command=self._nxperf_open_reports,height=38,fg_color=THEME["card2"],hover_color=THEME["border2"],text_color=THEME["text"]).pack(side="right",padx=3)
  body=ctk.CTkFrame(v,fg_color=THEME["card"],border_color=THEME["border"],border_width=1,corner_radius=12)
  body.grid(row=2,column=0,sticky="nsew",padx=16,pady=(5,14)); body.grid_rowconfigure(0,weight=1); body.grid_columnconfigure(0,weight=1)
  out=ctk.CTkTextbox(body,fg_color="#080D16",text_color=THEME["text"],font=("Consolas",13),wrap="word")
  out.grid(row=0,column=0,sticky="nsew",padx=8,pady=8)
  out.insert("1.0","Drücke „Diagnose ausführen“, um lokale Systemwerte, wichtige Laufzeiten und optionale Dienste zu prüfen.\n\nDiese Prüfung misst keine FPS und ändert keine Windows-Einstellungen. Sie hilft, reale Engpässe oder fehlende Komponenten zu finden.")
  out.configure(state="disabled")
  run.configure(command=lambda:_nxperf_run_diagnostics(self,out,status,run))
  yield None

AppExtension.b_performance_lab = _nxperf_builder
AppExtension._nxperf_export_report = _nxperf_export_report
AppExtension._nxperf_open_reports = _nxperf_open_reports

if __name__ == "__main__":
  last_error=None
  for _attempt in range(3):
    try:
      app_instance=AppExtension()
      app_instance.mainloop()
      break
    except SystemExit:
      raise
    except Exception as e:
      last_error=e
      write_crash_log(traceback.format_exc())
      try:app_instance.destroy()
      except Exception:pass
  else:
    raise last_error
